import { createReadStream, existsSync } from 'node:fs'
import { stat } from 'node:fs/promises'
import { extname, join, normalize, resolve } from 'node:path'
import { fileURLToPath, URL } from 'node:url'

import { defineConfig, type Plugin } from 'vite'

const apiDocsDir = fileURLToPath(new URL('./.api-docs', import.meta.url))

const apiDocsTypes: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
}

// The reference page is generated by `npm run build:docs` into .api-docs/ and is not part
// of the dev server's module graph, so serve it from there under /api/ in dev only. Once
// built, the assembler copies it into the Pages output and this middleware is not used.
const apiDocs: Plugin = {
  name: 'hugframe-api-docs',
  apply: 'serve',
  configureServer(server) {
    server.middlewares.use(async (request, response, next) => {
      const pathname = new URL(request.url ?? '/', 'http://localhost').pathname
      if (pathname !== '/api' && !pathname.startsWith('/api/')) return next()

      if (pathname === '/api') {
        response.writeHead(301, { location: '/api/' }).end()
        return
      }

      if (!existsSync(apiDocsDir)) {
        response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' })
        response.end(
          'The API reference is not built yet. Run `npm run build:docs` to generate it, then reload /api/.\n',
        )
        return
      }

      let relative = normalize(pathname.slice('/api'.length)).replace(/^\/+/, '')
      if (relative === '' || relative.endsWith('/')) relative = join(relative, 'index.html')

      const file = resolve(apiDocsDir, relative)
      if (!file.startsWith(apiDocsDir)) {
        response.writeHead(403).end('forbidden')
        return
      }

      try {
        const info = await stat(file)
        if (!info.isFile()) throw new Error('not a file')
        response.writeHead(200, {
          'content-type': apiDocsTypes[extname(file)] ?? 'application/octet-stream',
          'content-length': info.size,
          'cache-control': 'no-store',
        })
        createReadStream(file).pipe(response)
      } catch {
        response
          .writeHead(404, { 'content-type': 'text/plain; charset=utf-8' })
          .end(`not found: ${pathname}`)
      }
    })
  },
}

export default defineConfig({
  // The site is a multi-page build. Without this an unknown path silently falls back to
  // index.html, whose relative links then resolve against that stray URL and append a
  // segment on every click.
  appType: 'mpa',
  server: {
    port: 5176,
  },
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  build: {
    rollupOptions: {
      input: {
        index: fileURLToPath(new URL('./index.html', import.meta.url)),
        child: fileURLToPath(new URL('./child.html', import.meta.url)),
        playground: fileURLToPath(new URL('./playground/index.html', import.meta.url)),
      },
    },
  },
  plugins: [apiDocs],
})
